using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CoffeeProbe{static CoffeeProbe(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoffeeProbe.request"))return;File.Delete("CoffeeProbe.request");try{var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var flags=System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic;var fs=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.name.StartsWith("Circus_Circus")).ToArray();var rows=new System.Collections.Generic.List<string>();foreach(var f in fs){rows.Add(f.name+" "+f.transform.localToWorldMatrix);var d=typeof(FinalPNGCityDetails).GetMethod("Read",flags).Invoke(null,new object[]{f.sharedMesh});var p=(Vector3[])d.GetType().GetField("p").GetValue(d);var uv=(Vector2[][])d.GetType().GetField("uv").GetValue(d);var ids=(int[])d.GetType().GetField("ids").GetValue(d);var lines=new System.Collections.Generic.List<string>();lines.Add("i,x,y,z,u,v");for(int i=0;i<p.Length;i++){var w=f.transform.TransformPoint(p[i]);lines.Add(i+","+w.x+","+w.y+","+w.z+","+uv[0][i].x+","+uv[0][i].y);}File.WriteAllLines("FinalEnvironmentRoadReview/"+f.name+".csv",lines);File.WriteAllText("FinalEnvironmentRoadReview/"+f.name+"-ids.txt",string.Join(",",ids));var b=f.GetComponent<Renderer>().bounds;typeof(FinalPNGCityDetails).GetMethod("Capture",flags).Invoke(null,new object[]{s,b.center+new Vector3(0,0,65),b.center+Vector3.down*4,"Coffee-Before-"+f.name});}File.WriteAllLines("FinalEnvironmentRoadReview/CoffeeProbe.txt",rows);}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CoffeeProbe.txt",e.ToString());}}}
